INSERT INTO `food_tour_stops` VALUES (1,1,3,1,'Dạo quanh Chợ Sa (Cổ Loa) vào phiên chợ để cảm nhận không khí buôn bán tấp nập, tìm mua các loại nông sản tươi ngon đặc trưng của vùng như hành lá, khoai tây (có thể là sản phẩm OCOP từ HTX Cổ Loa) và hòa mình vào nét văn hóa địa phương. Bạn có thể mua một ít trái cây hoặc đồ ăn vặt bình dân với chi phí khoảng 50.000 - 80.000 VNĐ.','45 phút','2026-06-24 06:47:28','2026-06-24 06:47:28'),(2,3,2,1,'','45 phút','2026-07-24 04:29:07','2026-07-24 04:29:07'),(3,3,3,2,'','45 phút','2026-07-24 04:29:07','2026-07-24 04:29:07'),(4,7,3,1,'Dành thời gian dạo quanh các di tích lịch sử như Đền Thượng, Đình Ngự Triều Di Quy và Giếng Ngọc. Hãy lắng nghe những câu chuyện huyền thoại về vua An Dương Vương và nỏ thần Kim Quy để cảm nhận trọn vẹn giá trị văn hóa.','45 phút','2026-07-26 17:17:44','2026-07-26 17:17:44'),(5,7,3,2,'Thăm Chợ Sa vào phiên chợ để cảm nhận không khí buôn bán tấp nập của khu chợ cổ truyền. Dạo quanh các gian hàng, thưởng thức những món quà vặt địa phương, và ngắm nhìn cuộc sống đời thường của người dân Cổ Loa.','45 phút','2026-07-26 17:17:44','2026-07-26 17:17:44'),(6,7,3,3,'Khám phá và mua sắm các sản phẩm OCOP \'Bánh gạo lứt\' và \'Bánh vừng vòng\' của Công ty TNHH Hoàng Chiến Thắng. Đây là những món quà vặt truyền thống thơm ngon, bổ dưỡng, rất phù hợp để nhâm nhi khi \'chill\' hoặc làm quà tặng.','45 phút','2026-07-26 17:17:44','2026-07-26 17:17:44');
/*!40000 ALTER TABLE `food_tour_stops` ENABLE KEYS */;
UNLOCK TABLES;

