INSERT INTO `food_tours` VALUES (1,NULL,'Hành trình Hương vị Cổ Loa - Khám phá Chợ & Ẩm thực OCOP Đông Anh','hanh-trinh-huong-vi-co-loa-kham-pha-cho-am-thuc-ocop-dong-anh-8cd9f','Đắm mình vào không khí chợ truyền thống, khám phá những sản phẩm OCOP tinh hoa và kết thúc với món chè ngọt ngào đặc trưng của vùng đất Đông Anh.','2.5 giờ','5.0 km','350.000đ','✨ Lộ trình AI','17:00 - 21:00','Mới tạo','cheap','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80','Để trải nghiệm trọn vẹn bản sắc văn hóa và ẩm thực Đông Anh với ngân sách \'cheap\', chúng ta sẽ bắt đầu tại Chợ Sa cổ kính, nơi nhịp sống địa phương và câu chuyện lịch sử hòa quyện. Tiếp đó, khám phá hương vị OCOP độc đáo từ sản phẩm được chứng nhận của vùng. Cuối cùng, một bát chè truyền thống sẽ là điểm dừng chân hoàn hảo để kết thúc hành trình.','draft',1,NULL,NULL,'2026-06-24 06:47:28','2026-06-24 06:47:28'),(2,4,'Hành trình thư thái khám phá di sản và tinh hoa OCOP Đông Anh','hanh-trinh-thu-thai-kham-pha-di-san-va-tinh-hoa-ocop-dong-anh-09dc2','Hành trình đưa bạn rời xa ồn ào đô thị, hòa mình vào không gian cổ kính của Cổ Loa, thưởng thức nét ẩm thực và sản vật địa phương. Trải nghiệm các sản phẩm OCOP tinh hoa, mang đậm dấu ấn bản địa trong một không gian thư thái, yên bình.','2.5 giờ','5.0 km','350.000đ','✨ Lộ trình AI','17:00 - 21:00','Mới tạo','chill','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80','Đông Anh không chỉ có những con đường tấp nập mà còn ẩn chứa những giá trị văn hóa, lịch sử sâu sắc. Lộ trình này được thiết kế để bạn vừa khám phá kinh đô xưa, vừa chạm tới những nét ẩm thực và sản vật đặc trưng của vùng đất Cổ Loa. Đặc biệt, chúng tôi sẽ ưu tiên những sản phẩm OCOP chất lượng, thể hiện sự sáng tạo và tinh hoa của người dân địa phương, mang đến trải nghiệm \'chill\' đúng điệu.','draft',1,NULL,NULL,'2026-07-24 04:28:03','2026-07-24 04:28:03'),(3,4,'Tuấn Anh Nguyễn','tuan-anh-nguyen-f3035','wwwwwwwwwwwwwwwww','2.5 giờ','5.0 km','200.000đ','☕ Nhẹ nhàng','18:00 - 22:00','Mới tạo','chill','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80',NULL,'saved',0,NULL,NULL,'2026-07-24 04:29:07','2026-07-24 04:29:07'),(4,1,'Hành trình Đông Anh Cổ kính & Tinh hoa OCOP','hanh-trinh-dong-anh-co-kinh-tinh-hoa-ocop-0ee2c','Một hành trình thư thái khám phá những di tích lịch sử lâu đời và thưởng thức hương vị đặc sản OCOP mang đậm bản sắc văn hóa của Đông Anh.','2.5 giờ','5.0 km','350.000đ','✨ Lộ trình AI','17:00 - 21:00','Mới tạo','chill','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80','Để tìm về sự bình yên và kết nối với văn hóa địa phương, chúng ta sẽ bắt đầu tại Khu Di Tích Cổ Loa huyền thoại, nơi lắng đọng những câu chuyện lịch sử. Tiếp đó, đắm mình vào không khí sống động của Chợ Sa truyền thống, nơi giao thoa của văn hóa và ẩm thực. Cuối cùng, khép lại chuyến đi bằng việc thưởng thức những món bánh OCOP tinh hoa, mang đậm hương vị quê hương.','draft',1,NULL,NULL,'2026-07-26 16:43:55','2026-07-26 16:43:55'),(5,4,'Đông Anh Chill: Vị Ngon OCOP & Chuyện Chợ Xưa','dong-anh-chill-vi-ngon-ocop-chuyen-cho-xua-9bf39','Khám phá Đông Anh một cách thư thái qua hành trình ẩm thực kết hợp văn hóa, ưu tiên các sản phẩm OCOP tinh hoa bản địa. Tận hưởng không khí bình dị, thưởng thức đặc sản và kết thúc bằng món tráng miệng ngọt ngào.','2.5 giờ','5.0 km','350.000đ','✨ Lộ trình AI','17:00 - 21:00','Mới tạo','chill','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80','Bắt đầu chuyến đi bằng việc khám phá hương vị tinh hoa từ sản phẩm OCOP địa phương, nơi lưu giữ những nét ẩm thực truyền thống của Đông Anh. Tiếp đó, bạn sẽ đắm mình vào không gian Chợ Sa cổ kính, tìm hiểu về cuộc sống và ẩm thực của người dân Cổ Loa từ ngàn xưa. Kết thúc bằng một món chè thanh mát để thư giãn, hoàn thành một ngày trải nghiệm nhẹ nhàng, đậm chất Đông Anh.','draft',1,NULL,NULL,'2026-07-26 16:44:04','2026-07-26 16:44:04'),(6,1,'Hành trình Hương vị Cổ Loa - Chầm chậm Đông Anh','hanh-trinh-huong-vi-co-loa-cham-cham-dong-anh-5a921','Khám phá vẻ đẹp lịch sử và thưởng thức tinh hoa ẩm thực bản địa Đông Anh một cách thư thái, nhẹ nhàng. Một lộ trình hoàn hảo cho những tâm hồn tìm kiếm sự bình yên và hương vị truyền thống.','2.5 giờ','5.0 km','350.000đ','✨ Lộ trình AI','17:00 - 21:00','Mới tạo','chill','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80','Bắt đầu hành trình tại Cổ Loa, nơi lịch sử ngàn năm vang vọng, để cảm nhận hồn cốt của vùng đất. Tiếp nối, ta sẽ tìm đến những giá trị ẩm thực truyền thống, đặc biệt là sản phẩm OCOP, để nếm thử và hiểu thêm về công sức người dân. Cuối cùng, một món tráng miệng thanh mát sẽ khép lại chuyến đi, để lại dư vị ngọt ngào và những kỷ niệm khó quên về Đông Anh.','draft',1,NULL,NULL,'2026-07-26 17:13:34','2026-07-26 17:13:34'),(7,1,'Hành trình Vòng Ốc Cổ Loa: Chinh phục quá khứ, thưởng thức đặc sản','hanh-trinh-vong-oc-co-loa-chinh-phuc-qua-khu-thuong-thuc-dac-san-df317','Khám phá di sản ngàn năm của Đông Anh tại thành Cổ Loa, sau đó hòa mình vào không khí sôi động của chợ truyền thống và kết thúc bằng những thức quà OCOP tinh túy. Lộ trình này sẽ đưa bạn từ lịch sử hào hùng đến nét ẩm thực đậm đà bản sắc trong một buổi chiều \'chill\' đầy ý nghĩa.','2.5 giờ','5.0 km','350.000đ','✨ Lộ trình AI','17:00 - 21:00','Mới tạo','chill','https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80','Để thực sự cảm nhận Đông Anh, không thể bỏ qua trái tim văn hóa - Khu Di Tích Cổ Loa, nơi huyền thoại và lịch sử giao thoa. Tiếp nối dòng chảy cuộc sống, Chợ Sa kề bên sẽ là điểm dừng chân lý tưởng để bạn hòa mình vào nhịp sống thường nhật và khám phá những hương vị địa phương. Cuối cùng, ghé thăm cơ sở OCOP là cách tuyệt vời để thưởng thức và mang về những sản phẩm tinh hoa, khép lại một hành trình trải nghiệm sâu sắc và đáng nhớ.','draft',1,NULL,NULL,'2026-07-26 17:17:44','2026-07-26 17:17:44');
