INSERT INTO `market_messages` VALUES (1,16,NULL,'BQL Chợ Mạch Tràng','admin',NULL,'Chào mừng quý khách và bà con tiểu thương tham gia Phòng Chat Chợ Số 4.0 Mạch Tràng! Chúc bà con buôn may bán đắt.',NULL,NULL,NULL,NULL,'2026-07-23 08:28:59','2026-07-23 08:28:59'),(2,16,NULL,'Chủ sạp Cô Năm','merchant','Sạp rau quả Cô Năm','Rau cải ngọt Vân Nội sáng nay nhà em vừa hái xong, tươi rói không hóa chất nhé cả nhà ơi!',NULL,NULL,NULL,NULL,'2026-07-23 08:28:59','2026-07-23 08:28:59'),(3,16,NULL,'Nguyễn Minh','user',NULL,'Cô Năm ơi tí tầm 5h chiều con đi làm về qua lấy 1kg rau cải với 1 quả bí đỏ nha cô.',NULL,NULL,NULL,NULL,'2026-07-23 08:28:59','2026-07-23 08:28:59'),(4,16,NULL,'Chủ sạp Cô Năm','merchant','Sạp rau quả Cô Năm','Ok nha Minh ơi, cô để sẵn bọc riêng cho con nhé!',NULL,NULL,NULL,NULL,'2026-07-23 08:28:59','2026-07-23 08:28:59'),(5,16,4,'Thành viên Đông Anh','user',NULL,'hi',NULL,NULL,NULL,NULL,'2026-07-23 08:31:54','2026-07-23 08:31:54'),(6,16,4,'Thành viên Đông Anh','user',NULL,'gưgew',NULL,NULL,'Gian hàng Ăn uống Cô Sinh',NULL,'2026-07-23 08:35:03','2026-07-23 08:35:03'),(7,16,4,'Thành viên Đông Anh','user',NULL,'Sản phẩm này còn hàng không ạ?',NULL,NULL,'Gian hàng Ăn uống Cô Sinh',NULL,'2026-07-23 08:42:23','2026-07-23 08:42:23'),(8,16,4,'Thành viên Đông Anh','user',NULL,'Sản phẩm này còn hàng không ạ?',NULL,NULL,'Gian hàng Ăn uống Cô Sinh',NULL,'2026-07-23 08:42:25','2026-07-23 08:42:25'),(9,16,4,'Thành viên Đông Anh','user',NULL,'Sản phẩm này còn hàng không ạ?',NULL,NULL,'Gian hàng Ăn uống Cô Sinh',NULL,'2026-07-23 08:42:27','2026-07-23 08:42:27'),(10,16,4,'Thành viên Đông Anh','user',NULL,'Giá bao nhiêu vậy ạ?',NULL,NULL,'Gian hàng Ăn uống Cô Sinh',NULL,'2026-07-23 08:42:28','2026-07-23 08:42:28'),(11,16,4,'Thành viên Đông Anh','user',NULL,'Hàng có sẵn để qua lấy luôn không ạ?',NULL,NULL,'Gian hàng Ăn uống Cô Sinh',NULL,'2026-07-23 08:42:29','2026-07-23 08:42:29'),(12,16,4,'Thành viên Đông Anh','user',NULL,'Nhớ bọc kỹ giúp mình nhé!',NULL,NULL,'Gian hàng 